using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;

namespace XConnect.Tests;

/// <summary>Thrown by the request audit when an SDK request does not match the official OpenAPI contract.</summary>
internal sealed class SpecViolationException(string message) : Exception(message);

/// <summary>
/// The compact OpenAPI contract (<c>docs/spec-snapshot.json</c>, generated by <c>tools/generate_coverage.py</c>): parameters, request bodies and
/// success responses of every operation the SDK implements, with the schemas they reach. Used to audit every request the unit tests send and to
/// compare the response models with the documented schemas.
/// </summary>
internal sealed class SpecContract
{
    private static readonly Lazy<SpecContract> Lazy = new(() => new SpecContract());

    public static SpecContract Instance => Lazy.Value;

    private readonly List<Operation> _operations = [];
    private readonly JsonObject _schemas;

    private SpecContract()
    {
        var root = JsonNode.Parse(File.ReadAllText(Path.Combine(SpecConformanceTests.RepositoryRoot, "docs/spec-snapshot.json")))!.AsObject();
        _schemas = root["schemas"]!.AsObject();
        foreach (var op in root["operations"]!.AsArray())
        {
            var path = op!["path"]!.GetValue<string>();
            var pattern = new Regex("^" + Regex.Replace(Regex.Escape(path), @"\\\{[^}]+\}", "[^/]+") + "$", RegexOptions.CultureInvariant);
            _operations.Add(new Operation(op["method"]!.GetValue<string>(), path, pattern, path.Count(c => c == '{'), op["contract"]?.AsObject()));
        }
    }

    public sealed record Operation(string Method, string Path, Regex Pattern, int ParameterSegments, JsonObject? Contract)
    {
        public string Key => $"{Method} {Path}";
    }

    public IEnumerable<Operation> Operations => _operations;

    public Operation? Find(string key) => _operations.FirstOrDefault(o => o.Key == key);

    /// <summary>Finds the operation a concrete request addresses; literal segments beat parameter segments (<c>/2/users/me</c> over <c>/2/users/{id}</c>).</summary>
    public Operation? Match(string method, string absolutePath) =>
        _operations.Where(o => o.Method == method && o.Pattern.IsMatch(absolutePath)).OrderBy(o => o.ParameterSegments).FirstOrDefault();

    public JsonNode Resolve(JsonNode node)
    {
        var seen = 0;
        while (node is JsonObject o && o["ref"] is JsonNode r && seen++ < 50)
        {
            node = _schemas[r.GetValue<string>()]!;
        }

        return node;
    }

    /// <summary>The property schemas, required names and openness of an object schema, merging <c>allOf</c>/<c>oneOf</c>/<c>anyOf</c> members.</summary>
    public (Dictionary<string, JsonNode> Props, HashSet<string> Required, bool Open, bool HasShape) Shape(JsonNode node)
    {
        var props = new Dictionary<string, JsonNode>();
        var required = new HashSet<string>();
        var open = false;
        var hasShape = false;
        Merge(node, true, 0);
        return (props, required, open, hasShape);

        void Merge(JsonNode n, bool requiredCounts, int depth)
        {
            var o = Resolve(n).AsObject();
            if (depth > 12)
            {
                return;
            }

            if (o["props"] is JsonObject p)
            {
                hasShape = true;
                foreach (var (k, v) in p)
                {
                    props[k] = v!;
                }
            }

            if (o["req"] is JsonArray r && requiredCounts)
            {
                foreach (var name in r)
                {
                    required.Add(name!.GetValue<string>());
                }
            }

            open |= o["open"] is not null;
            foreach (var (key, counts) in new[] { ("allOf", requiredCounts), ("oneOf", false), ("anyOf", false) })
            {
                if (o[key] is JsonArray members)
                {
                    foreach (var member in members)
                    {
                        Merge(member!, counts, depth + 1);
                    }
                }
            }
        }
    }

    /// <summary>Checks a request the SDK sent against the operation's contract. Returns the problems found (empty when it conforms).</summary>
    public List<string> ValidateRequest(Operation op, string? rawQuery, string? contentType, string? body)
    {
        var problems = new List<string>();
        if (op.Contract is null)
        {
            return problems;
        }

        var parameters = op.Contract["parameters"]!.AsArray().Select(p => p!.AsObject()).Where(p => p["in"]!.GetValue<string>() == "query").ToList();
        var sent = new List<(string Name, string Value)>();
        foreach (var pair in (rawQuery ?? string.Empty).TrimStart('?').Split('&', StringSplitOptions.RemoveEmptyEntries))
        {
            var i = pair.IndexOf('=');
            sent.Add((Uri.UnescapeDataString(i < 0 ? pair : pair[..i]), Uri.UnescapeDataString(i < 0 ? string.Empty : pair[(i + 1)..])));
        }

        foreach (var (name, value) in sent)
        {
            var parameter = parameters.FirstOrDefault(p => p["name"]!.GetValue<string>() == name);
            if (parameter is null)
            {
                problems.Add($"query parameter '{name}' is not defined for {op.Key}");
                continue;
            }

            CheckQueryValue(parameter["schema"]!, name, value, problems);
        }

        foreach (var required in parameters.Where(p => p["required"]!.GetValue<bool>()))
        {
            var name = required["name"]!.GetValue<string>();
            if (sent.All(s => s.Name != name))
            {
                problems.Add($"required query parameter '{name}' is missing for {op.Key}");
            }
        }

        if (body is not null && contentType == "application/json" && op.Contract["body"]?["application/json"] is { } schema)
        {
            try
            {
                CheckJson(schema, JsonNode.Parse(body), "body", problems);
            }
            catch (JsonException ex)
            {
                problems.Add($"request body is not valid JSON: {ex.Message}");
            }
        }
        else if (contentType is null && body is null && op.Contract["body"]?["application/json"] is { } requiredBody && Shape(requiredBody) is { Required.Count: > 0 })
        {
            problems.Add($"{op.Key} requires a JSON body with {string.Join(", ", Shape(requiredBody).Required)}");
        }

        return problems;
    }

    private void CheckQueryValue(JsonNode schemaNode, string name, string value, List<string> problems)
    {
        var schema = Resolve(schemaNode).AsObject();
        var type = schema["type"]?.GetValue<string>();
        if (type == "array")
        {
            var items = schema["items"] ?? new JsonObject();
            var values = value.Split(',');
            if (schema["minItems"] is { } min && values.Length < min.GetValue<int>())
            {
                problems.Add($"query '{name}' needs at least {min.GetValue<int>()} value(s)");
            }

            if (schema["maxItems"] is { } max && values.Length > max.GetValue<int>())
            {
                problems.Add($"query '{name}' accepts at most {max.GetValue<int>()} value(s), got {values.Length}");
            }

            foreach (var v in values)
            {
                CheckQueryValue(items, name, v, problems);
            }

            return;
        }

        switch (type)
        {
            case "integer":
                if (!long.TryParse(value, out var number))
                {
                    problems.Add($"query '{name}'='{value}' is not an integer");
                }
                else
                {
                    if (schema["min"] is { } lo && number < lo.GetValue<long>())
                    {
                        problems.Add($"query '{name}'={number} is below the minimum {lo.GetValue<long>()}");
                    }

                    if (schema["max"] is { } hi && number > hi.GetValue<long>())
                    {
                        problems.Add($"query '{name}'={number} is above the maximum {hi.GetValue<long>()}");
                    }
                }

                break;
            case "boolean":
                if (value is not ("true" or "false"))
                {
                    problems.Add($"query '{name}'='{value}' is not a boolean");
                }

                break;
            default:
                if (schema["enum"] is JsonArray allowed && allowed.All(a => a!.ToString() != value))
                {
                    problems.Add($"query '{name}'='{value}' is not one of: {string.Join(", ", allowed.Select(a => a!.ToString()))}");
                }

                break;
        }
    }

    private void CheckJson(JsonNode schemaNode, JsonNode? value, string at, List<string> problems)
    {
        var schema = Resolve(schemaNode).AsObject();
        var type = schema["type"]?.GetValue<string>();
        var (props, required, open, hasShape) = Shape(schema);

        if (value is null)
        {
            problems.Add($"{at} is null; the SDK must omit absent values");
            return;
        }

        if (value is JsonObject obj && (type == "object" || hasShape))
        {
            if (hasShape && !open)
            {
                foreach (var key in obj.Select(kv => kv.Key).Where(k => !props.ContainsKey(k)))
                {
                    problems.Add($"{at}.{key} is not defined in the schema");
                }
            }

            foreach (var name in required.Where(n => !obj.ContainsKey(n)))
            {
                problems.Add($"{at}.{name} is required by the schema but missing");
            }

            foreach (var (key, child) in obj)
            {
                if (props.TryGetValue(key, out var childSchema))
                {
                    CheckJson(childSchema, child, $"{at}.{key}", problems);
                }
            }

            return;
        }

        var kind = value.GetValueKind();
        switch (type)
        {
            case "string" when kind != JsonValueKind.String:
            case "boolean" when kind is not (JsonValueKind.True or JsonValueKind.False):
            case "integer" when kind != JsonValueKind.Number || !value.ToJsonString().All(c => char.IsDigit(c) || c == '-'):
            case "number" when kind != JsonValueKind.Number:
            case "array" when kind != JsonValueKind.Array:
            case "object" when kind != JsonValueKind.Object:
                problems.Add($"{at} should be {type} but is {kind}");
                return;
        }

        if (value is JsonArray array)
        {
            if (schema["items"] is { } items)
            {
                for (var i = 0; i < array.Count; i++)
                {
                    CheckJson(items, array[i], $"{at}[{i}]", problems);
                }
            }

            if (schema["maxItems"] is { } max && array.Count > max.GetValue<int>())
            {
                problems.Add($"{at} has {array.Count} items, the schema allows {max.GetValue<int>()}");
            }

            if (schema["minItems"] is { } min && array.Count < min.GetValue<int>())
            {
                problems.Add($"{at} has {array.Count} items, the schema needs {min.GetValue<int>()}");
            }
        }
        else if (kind == JsonValueKind.String && schema["enum"] is JsonArray allowed && allowed.All(a => a!.ToString() != value.GetValue<string>()))
        {
            problems.Add($"{at}='{value}' is not one of: {string.Join(", ", allowed.Select(a => a!.ToString()))}");
        }
        else if (kind == JsonValueKind.Number && value.ToJsonString() is var text && long.TryParse(text, out var n))
        {
            if (schema["min"] is { } lo && n < lo.GetValue<long>())
            {
                problems.Add($"{at}={n} is below the minimum {lo.GetValue<long>()}");
            }

            if (schema["max"] is { } hi && n > hi.GetValue<long>())
            {
                problems.Add($"{at}={n} is above the maximum {hi.GetValue<long>()}");
            }
        }
    }
}
